/**
 * Sequence Alignment & Mutation Classification Module
 * Part of CS112 Term Project: BioLCS (Plant Genomics Mutation Tracking)
 * 
 * Maps LCS back to global pairwise sequence alignment and classifies mutations into:
 * - MATCH: Conserved nucleotide position (marked with '|')
 * - DELETION: Nucleotide missing in sequence Y (gap '-' in Y)
 * - INSERTION: Nucleotide newly inserted in sequence Y (gap '-' in X)
 */

/**
 * Builds pairwise alignment from traceback matrix generated by Grid DP.
 * 
 * @param {string} xSeq
 * @param {string} ySeq
 * @param {string[][]} tracebackMatrix
 * @returns {object}
 */
export function generateAlignmentFromTraceback(xSeq = "", ySeq = "", tracebackMatrix = []) {
  let currI = xSeq.length;
  let currJ = ySeq.length;
  const xRev = [];
  const yRev = [];
  const patRev = [];
  const mutRev = [];

  while (currI > 0 || currJ > 0) {
    const arrow = (currI > 0 && currJ > 0) ? tracebackMatrix[currI][currJ] : (currI > 0 ? "UP" : "LEFT");

    if (arrow === "DIAG") {
      const char = xSeq[currI - 1];
      xRev.push(char);
      yRev.push(char);
      patRev.push("|");
      mutRev.push({ type: "MATCH", charX: char, charY: char });
      currI--;
      currJ--;
    } else if (arrow === "UP") {
      const char = xSeq[currI - 1];
      xRev.push(char);
      yRev.push("-");
      patRev.push("-");
      mutRev.push({ type: "DELETION", charX: char, charY: "-" });
      currI--;
    } else {
      const char = ySeq[currJ - 1];
      xRev.push("-");
      yRev.push(char);
      patRev.push("-");
      mutRev.push({ type: "INSERTION", charX: "-", charY: char });
      currJ--;
    }
  }

  const xAligned = xRev.reverse().join("");
  const yAligned = yRev.reverse().join("");
  const matchPattern = patRev.reverse().join("");
  const mutations = mutRev.reverse().map((m, idx) => ({ ...m, index: idx }));

  return summarizeAlignment(xAligned, yAligned, matchPattern, mutations, xSeq.length, ySeq.length);
}

/**
 * Builds pairwise alignment given sequences and recovered LCS string.
 * Used for Hirschberg or any generic LCS solution.
 * 
 * @param {string} xSeq
 * @param {string} ySeq
 * @param {string} lcsStr
 * @returns {object}
 */
export function generateAlignment(xSeq = "", ySeq = "", lcsStr = "") {
  // If traceback matrix was passed instead of lcs string
  if (Array.isArray(lcsStr)) {
    return generateAlignmentFromTraceback(xSeq, ySeq, lcsStr);
  }

  // Find greedy forward embedding indices for LCS characters
  const posInX = [];
  let pX = 0;
  for (const ch of lcsStr) {
    while (pX < xSeq.length && xSeq[pX] !== ch) pX++;
    posInX.push(pX);
    pX++;
  }

  const posInY = [];
  let pY = 0;
  for (const ch of lcsStr) {
    while (pY < ySeq.length && ySeq[pY] !== ch) pY++;
    posInY.push(pY);
    pY++;
  }

  let xAligned = "";
  let yAligned = "";
  let matchPattern = "";
  const mutations = [];

  let idxX = 0;
  let idxY = 0;

  for (let k = 0; k < lcsStr.length; k++) {
    const targetX = posInX[k];
    const targetY = posInY[k];

    // Emit deletions for X before match k
    while (idxX < targetX) {
      xAligned += xSeq[idxX];
      yAligned += "-";
      matchPattern += "-";
      mutations.push({ type: "DELETION", charX: xSeq[idxX], charY: "-", index: mutations.length });
      idxX++;
    }

    // Emit insertions for Y before match k
    while (idxY < targetY) {
      xAligned += "-";
      yAligned += ySeq[idxY];
      matchPattern += "-";
      mutations.push({ type: "INSERTION", charX: "-", charY: ySeq[idxY], index: mutations.length });
      idxY++;
    }

    // Emit match k
    xAligned += xSeq[idxX];
    yAligned += ySeq[idxY];
    matchPattern += "|";
    mutations.push({ type: "MATCH", charX: xSeq[idxX], charY: ySeq[idxY], index: mutations.length });
    idxX++;
    idxY++;
  }

  // Trailing deletions in X
  while (idxX < xSeq.length) {
    xAligned += xSeq[idxX];
    yAligned += "-";
    matchPattern += "-";
    mutations.push({ type: "DELETION", charX: xSeq[idxX], charY: "-", index: mutations.length });
    idxX++;
  }

  // Trailing insertions in Y
  while (idxY < ySeq.length) {
    xAligned += "-";
    yAligned += ySeq[idxY];
    matchPattern += "-";
    mutations.push({ type: "INSERTION", charX: "-", charY: ySeq[idxY], index: mutations.length });
    idxY++;
  }

  return summarizeAlignment(xAligned, yAligned, matchPattern, mutations, xSeq.length, ySeq.length);
}

/**
 * Summarizes alignment metrics.
 */
function summarizeAlignment(xAligned, yAligned, matchPattern, mutations, originalLenX, originalLenY) {
  const matchCount = mutations.filter(m => m.type === "MATCH").length;
  const deletionCount = mutations.filter(m => m.type === "DELETION").length;
  const insertionCount = mutations.filter(m => m.type === "INSERTION").length;
  const totalCols = xAligned.length;

  const maxLen = Math.max(originalLenX, originalLenY);
  const similarityPercentage = maxLen > 0 ? Number(((matchCount / maxLen) * 100).toFixed(2)) : 100;

  return {
    xAligned,
    yAligned,
    matchPattern,
    mutations,
    summary: {
      totalLength: totalCols,
      matchCount,
      deletionCount,
      insertionCount,
      similarityPercentage
    }
  };
}
